const titre = el('a', '', c.querySelector('h3')?.textContent || ''); titre.href = c.querySelector('h3 a')?.href || '#';
s.append(el('strong', '', ''), el('small', '', `${enCours(c) ? '● ' + T.live + ' · ' : ''}${c.querySelector('.date')?.textContent || ''} · ${c.dataset.heure}`));
